def backfill_operation_codes(apps, schema_editor):
    """Links each existing row to its Section C operation by the "C1. ..." prefix of its
    activity description (not by row order — the workbook lists them out of order),
    and adds the C7 row the workbook never had, at rate 0."""
    InHouseHourRate = apps.get_model("reference", "InHouseHourRate")
    for row in InHouseHourRate.objects.filter(operation_code__isnull=True):
        match = re.match(r"\s*C([1-7])\b", row.activity_description, re.IGNORECASE)
        if not match:
            continue
        code = f"c{match.group(1)}"
        if InHouseHourRate.objects.filter(operation_code=code).exists():
            continue
        row.operation_code = code
        full = WORKBOOK_RATES.get(code)
        # Only an untouched seeded rate is restored to full precision, never an edited one.
        if full is not None and row.mhr_rate == round(full, 2):
            row.mhr_rate = full
        row.save(update_fields=["operation_code", "mhr_rate"])

    if InHouseHourRate.objects.exists() and not InHouseHourRate.objects.filter(operation_code="c7").exists():
        last = InHouseHourRate.objects.order_by("-order").first()
        InHouseHourRate.objects.create(
            cost_head="C7. Hub Pre-Turning",
            operation="Lathe turning",
            activity_description="C7. Hub Pre-Turning",
            operation_code="c7",
            mhr_rate=0,
            order=last.order + 1,
        )


